create function public.save_dataset(p_actor uuid,p_version text,p_content jsonb,p_source text,p_license text,p_publish boolean,p_hash text) returns void language plpgsql security definer set search_path='' as $$begin
 perform public.require_admin(p_actor,true);
 if jsonb_typeof(p_content)<>'object' or (select count(*) from jsonb_object_keys(p_content))<>12 or length(trim(p_license))<3 or length(trim(p_source))<10 then raise exception 'dataset invalid';end if;
 if not p_content ?& array['ngay-sinh','gio-sinh','hop-tuoi','tinh-duyen','than-so-hoc','chi-tay','nhan-tuong','phu-the','giac-mo','phong-thuy','cong-danh','ten-may-man'] or p_content::text ~ '[<>]' or exists(select 1 from jsonb_each(p_content) as e where jsonb_typeof(e.value->'sections') is distinct from 'array' or length(e.value->>'title')<3 or (select array_length(regexp_split_to_array(trim(string_agg(value,' ')),'\s+'),1) from jsonb_array_elements_text(e.value->'sections'))<501) then raise exception 'content invalid';end if;
 -- Recompute SHA-256 on PostgreSQL canonical jsonb; never trust a client digest.
 p_hash:=encode(sha256(convert_to(p_content::text,'UTF8')),'hex');
 insert into public.dataset_versions(version,content,hash,source_metadata,state) values(p_version,p_content,p_hash,jsonb_build_object('source',p_source,'license',p_license),case when p_publish then 'published' else 'draft' end) on conflict(version) do update set content=p_content,hash=p_hash,source_metadata=excluded.source_metadata,state=excluded.state,updated_at=now();
 insert into public.audit_events(actor,action,changed_fields) values(p_actor,case when p_publish then 'dataset_published' else 'dataset_draft' end,array['version','hash']);end$$;
create function public.set_member(p_actor uuid,p_user uuid,p_role text,p_active boolean) returns void language plpgsql security definer set search_path='' as $$begin
 perform pg_advisory_xact_lock(812991);perform public.require_admin(p_actor,true);
 if p_actor=p_user then raise exception 'cannot change own role';end if;
 if p_active and not exists(select 1 from public.admin_members where user_id=p_user and active) and (select count(*) from public.admin_members where active)>=3 then raise exception 'maximum 3 admins';end if;
 insert into public.admin_members(user_id,role,active) values(p_user,p_role,p_active) on conflict(user_id) do update set role=p_role,active=p_active,updated_at=now();insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'member_changed',p_user,array['role','active']);end$$;
create function public.moderate_review(p_actor uuid,p_review uuid,p_approve boolean) returns void language plpgsql security definer set search_path='' as $$begin perform public.require_admin(p_actor);update public.reviews set moderation_state=case when p_approve then 'approved' else 'rejected' end,updated_at=now() where id=p_review;insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'review_moderated',p_review,array['moderation_state']);end$$;
revoke all on function public.save_dataset(uuid,text,jsonb,text,text,boolean,text),public.set_member(uuid,uuid,text,boolean),public.moderate_review(uuid,uuid,boolean) from public,anon,authenticated;
grant execute on function public.save_dataset(uuid,text,jsonb,text,text,boolean,text),public.set_member(uuid,uuid,text,boolean),public.moderate_review(uuid,uuid,boolean) to service_role;
